var FULLNAMEOF={DL09:["openStuQuick","student_id"],DL02:["leadDetail","lead_id"],DL01:["openNSQuick","staff_id"]};
function cellLnk(r,c,cfg){
 var d=(c[0]==="full_name")?FULLNAMEOF[cfg.code]:CELLLNK[c[0]];
 if(!d)return null;
 var id=String(r[d[1]]==null?"":r[d[1]]).trim();
 if(!id)return null;
 var txt=String(r[c[0]]==null?"":r[c[0]]).trim();
 if(!txt)return null;
 return '<a class="lnk" onclick="'+d[0]+'(\''+esc(id)+'\')">'+esc(txt)+'</a>'}
/* Nút thao tác ĐÚNG NGHIỆP VỤ cho từng dòng: lấy thẳng việc mà bộ máy SLA đang treo lên bản ghi
   đó - nút hiện ra chính là việc trợ thủ sẽ bảo làm. Không khai lại lần thứ hai ở từng bảng.
   (anh Luân: "thao tác khiếu nại chỗ này ko chuẩn rồi") */
function rowActMap(){
 if(window.__rowActT===DVER&&window.__rowAct)return window.__rowAct;
 var m={};try{slaItems().forEach(function(x){if(x.rid!=null&&!m[String(x.rid)])m[String(x.rid)]=x})}catch(e){}
 window.__rowAct=m;window.__rowActT=DVER;return m}
function rowSlaBtn(r,pk){
 var x=rowActMap()[String(r[pk]==null?"":r[pk])];
 if(!x||!x.act)return "";
 return '<button class="btn primary sm" onclick="slaAct(\''+esc(x.act)+'\',\''+esc(String(x.rid||""))+'\')" data-tip="'+esc(String(x.what||"").slice(0,90))+'"><i class="ti ti-tool"></i>Làm ngay</button>'}
function tableHTML(cfg,data,key){var act=cfg.act||[];var pk=cfg.cols[0][0];
 hideInit(key);var cols=cfg.cols.filter(function(c){return colVisible(key,c[0])});if(!cols.length)cols=[cfg.cols[0]];
 var h='<div class="tbwrap"><table class="dt"><thead><tr>';
 var so=(window.SORT||{})[key];
 cols.forEach(function(c){var on=so&&so.col===c[0];
  h+='<th style="cursor:pointer" onclick="listSort(\''+key+'\',\''+c[0]+'\')" title="Bấm để sắp xếp">'+esc(c[1])+(on?(so.dir>0?' ▲':' ▼'):'')+'</th>'});
 h+='<th>Thao tác</th>';
 h+='</tr></thead><tbody>';
 if(!data.length){var isF=(SEARCH[key]||(FILT[key]||[]).length||(window.QF||{})[key]||((key==="hocvien")&&(window.HVFCLS||window.HVFCRS)));
  h+='<tr><td class="empty" colspan="'+(cols.length+1)+'">'+(isF?'Không có bản ghi khớp BỘ LỌC hiện tại. <button class="btn sm" onclick="clearFilt(\''+key+'\')" style="margin-left:8px"><i class="ti ti-x"></i>Xóa lọc</button>':'Chưa có bản ghi nào trong bảng này.')+'</td></tr>'}
 data.forEach(function(r){var id=esc(String(r[pk]||""));h+='<tr>';
  cols.forEach(function(c){
    if(!cfg.ro&&cfg.filt&&c[0]===cfg.filt&&ENUMMAP[cfg.filt]&&ENUM[ENUMMAP[cfg.filt]]){h+='<td>'+qsel(key,id,cfg.filt,r[c[0]])+'</td>';return}
    var lk=(c[2]==="chip"||c[2]==="enum"||c[2]==="money"||c[2]==="na"||c[2]==="calcso"||c[2]==="lau")?null:cellLnk(r,c,cfg);
    if(lk){h+='<td>'+lk+'</td>';return}
    h+='<td'+(c[2]==="money"?' style="text-align:right;font-variant-numeric:tabular-nums"':'')+'>'+cell(r,c,cfg.code)+'</td>'});
  h+='<td><div class="rowact">'+rowSlaBtn(r,pk)+(cfg.ro?'':'<button class="btn sm" onclick="openEdit(\''+key+'\',\''+id+'\')"><i class="ti ti-edit"></i>Sửa</button>')+
   act.map(function(a){return '<button class="btn sm" onclick="'+a.fn+'(\''+esc(String(r[a.arg]||""))+'\')"><i class="ti '+a.ic+'"></i>'+a.lb+'</button>'}).join("")+'</div></td>';
  h+='</tr>'});
 return h+'</tbody></table></div>'}

/* ═══════════ V9.28 BỘ MÁY LỌC CHUYÊN SÂU (việc B - anh Luân 28/07) ═══════════
   "hầu hết các trang đều cần, đừng nhầm với tab - tab hiện tại đã ngon, chỉ bổ sung filter,
    các filter này có thể kết hợp, có thể lưu cho cá nhân dùng".

   LUẬT: KHÔNG vá tay từng trang. 50 hàm render mà mỗi trang một kiểu thì sửa một luật phải
   sửa 50 chỗ - đúng lớp lỗi tốn công nhất của dự án này. Mỗi trang chỉ KHAI các trục nó cần;
   bộ máy lo giao diện, kết hợp điều kiện, đếm số, xoá lọc và lưu bộ lọc riêng của từng người.
   VÀ giữa các trục · HOẶC trong cùng một trục · không đụng gì tới tab.

   Trục khai bằng fx*(...). MỌI trục đều đi qua fltColOk() - trục trỏ vào cột KHÔNG CÓ THẬT thì
   bị loại và _check17 báo đỏ. (Chính người viết đã từng soi cột wow_teacher_id không tồn tại
   rồi báo cáo 69 lỗi ma - không để lặp lại.) */
function fltColOk(code,c){var rs=rows(code);
 for(var i=0;i<rs.length;i++)if(Object.prototype.hasOwnProperty.call(rs[i],c))return true;
 return false}
/* --- khai trục --- */
function fxEnum(c,t){return {k:c,t:t,ty:"multi",col:c,get:function(r){return ecode(r[c])},
 lab:function(v,all){for(var i=0;i<all.length;i++)if(ecode(all[i][c])===v)return elabel(all[i][c])||v;return v}}}
function fxStaff(c,t){return {k:c,t:t,ty:"multi",col:c,get:function(r){return String(r[c]||"")},
 lab:function(v){var s=find("DL01","staff_id",v);return s?(s.full_name+" · "+v):(v||"(chưa gán)")}}}
function fxRef(c,t,code,idf,nmf){return {k:c,t:t,ty:"multi",col:c,get:function(r){return String(r[c]||"")},
 lab:function(v){var x=find(code,idf,v);return x?(x[nmf]||v):(v||"(chưa có)")}}}
function fxDate(c,t){return {k:c,t:t,ty:"date",col:c,get:function(r){return r[c]}}}
function fxCalc(k,t,getter,labeler){return {k:k,t:t,ty:"multi",col:null,get:getter,lab:labeler||function(v){return v}}}

