var JBY={};JSTAGE.forEach(function(s,i){s.idx=i;JBY[s.k]=s});
var JMAIN=["new","contacted","test_booked","test_grading","test_done","consult","enrolled","paid","onboarding","learning","ending","reenroll","alumni"];
var JBRANCH=["no_contact","lost","paused","cancelled"];
/* ===== V9.15 - TẦNG CHẶNG VÒNG ĐỜI (arc) phủ TRÊN 17 chặng nghiệp vụ =====
   4 chặng lớn đúng cách Luân nghĩ về một con người: còn theo đuổi không -
   đang học - tạm dừng - kết thúc/học tiếp. KHÔNG đổi jStageOf; đây chỉ là
   lớp GỘP để menu, trang chặng và hệ node nói cùng một ngôn ngữ. */
var ARCS=[
 {k:"changA",n:1,t:"Khách tiềm năng",ic:"ti-user-plus",col:"#3B82C4",
  d:"Từ lead mới tới lúc đóng tiền. Còn theo đuổi hay đã ngưng đều nằm ở đây - ngưng rồi vẫn chăm lại được."},
 {k:"changB",n:2,t:"Đang học",ic:"ti-school",col:"#0D9488",
  d:"Từ lúc thu đủ tiền: xếp lớp - onboarding - học, dạy, chăm mỗi ngày."},
 {k:"changC",n:3,t:"Tạm dừng",ic:"ti-player-pause",col:"#E08A1E",
  d:"Nghỉ ngang, bảo lưu, hủy đăng ký. Giữ chân được thì giữ, không thì xử lý cho trọn (hoàn tiền, hẹn quay lại)."},
 {k:"changD",n:4,t:"Kết thúc & Học tiếp",ic:"ti-award",col:"#7C3AED",
  d:"Ra kết quả đầu ra, mời học tiếp, xin giới thiệu bạn bè - vòng đời quay lại từ đầu."}];
var ARCBK={};ARCS.forEach(function(a){ARCBK[a.k]=a});
/* Tên nhóm chặng trên menu: "C1 · Khách tiềm năng". Một chỗ sinh ra, mọi chỗ dùng lại. */
function arcGrpName(k){var A=ARCBK[k];return A?("C"+A.n+" · "+A.t):k}
var ARCOF={new:"changA",contacted:"changA",test_booked:"changA",test_grading:"changA",
 test_done:"changA",consult:"changA",enrolled:"changA",no_contact:"changA",lost:"changA",
 paid:"changB",onboarding:"changB",learning:"changB",
 paused:"changC",cancelled:"changC",
 ending:"changD",reenroll:"changD",alumni:"changD"};
function arcOf(k){return ARCOF[k]||"changA"}
/* chặng nghiệp vụ CHÍNH vẽ trên đường ray của từng arc (đúng thứ tự dòng chảy) */
var ARCRAIL={
 changA:["new","contacted","test_booked","test_grading","test_done","consult","enrolled"],
 changB:["paid","onboarding","learning"],
 changC:["paused","cancelled"],
 changD:["ending","reenroll","alumni"]};
/* ga RẼ NHÁNH vẽ kèm dưới ray (hình thoi): rơi khỏi dòng chảy chính */
var ARCBRANCH={changA:["no_contact","lost"],changB:[],changC:[],changD:[]};
function goArc(a){window.ARC=a;window.CHANGK="";go("chang")}
/* NODE TANG 2 - dai hat hanh trinh gan tren tung dong danh sach.
   Nhin 1 giay biet: nguoi nay o chang lon nao (C1..C4), toi hat thu may, co qua han khong.
   Hat to = dang dung o day; hat mo = da qua; hat xam = chua toi; hinh thoi do = re nhanh. */
function mstrip(k,over,pid){var S=JBY[k];if(!S)return "";
 var a=arcOf(k),A=ARCBK[a],rail=ARCRAIL[a]||[],ci=rail.indexOf(k),br=ci<0;
 var tt="Chặng "+A.n+" · "+A.t+" - đang ở: "+S.t+(br?" (rẽ nhánh)":" (bước "+(ci+1)+"/"+rail.length+")")+(over?" · QUÁ HẠN":"")+(pid?" - bấm một hạt để xem chặng đó để lại gì":"");
 var oc=pid?' onclick="event.stopPropagation();mstripOpen(\''+esc(pid)+'\')"':''; /* V9.18: node bấm được - mở chi tiết từng chặng */
 var h='<span class="mstrip'+(pid?" clk":"")+'" style="--mscol:'+A.col+'" data-tip="'+esc(tt)+'"'+oc+'><span class="msarc" data-tip="'+esc("Chặng "+A.n+" · "+A.t)+'">C'+A.n+'</span>';
 /* V9.27: MỖI HẠT có chú thích riêng - rê vào hạt nào biết ngay đó là bước gì, đã qua hay chưa tới.
    V9.54 (anh Luân): "qua là qua cái gì?" - chú thích phải kể luôn SẢN PHẨM chặng đó để lại, và
    bấm vào hạt là mở ngăn kéo của đúng chặng đó. Sản phẩm tính lúc rê (data-tipfn) chứ không dựng
    sẵn: một trang danh sách có cả trăm dòng, mỗi dòng bảy hạt, dựng sẵn là đọc lại hồ sơ 700 lần. */
 rail.forEach(function(rk,i){var st=JBY[rk]||{};
  var tr=br?"đã rẽ nhánh khỏi đường chính":(i<ci?"đã qua":(i===ci?("ĐANG Ở ĐÂY"+(over?" · QUÁ HẠN":"")):"chưa tới"));
  var cls="msd"+(br?"":(i<ci?" done":(i===ci?" now"+(over?" over":""):"")));
  var nen="Bước "+(i+1)+"/"+rail.length+" · "+(st.t||rk)+" - "+tr;
  if(pid)h+='<span class="'+cls+' clk" data-tipfn="mstripTip" data-tipa="'+esc(pid+"|"+rk+"|"+nen)+'" onclick="event.stopPropagation();jStagePop(\''+esc(pid)+'\',\''+esc(rk)+'\')"></span>';
  else h+='<span class="'+cls+'" data-tip="'+esc(nen)+'"></span>'});
 if(br)h+=pid?('<span class="msd br clk'+(over?" over":"")+'" data-tipfn="mstripTip" data-tipa="'+esc(pid+"|"+k+"|Rẽ nhánh · "+S.t+(over?" - QUÁ HẠN":""))+'" onclick="event.stopPropagation();jStagePop(\''+esc(pid)+'\',\''+esc(k)+'\')"></span>')
  :('<span class="msd br'+(over?" over":"")+'" data-tip="'+esc("Rẽ nhánh · "+S.t+(over?" - QUÁ HẠN":""))+'"></span>');
 return h+'</span>'}
TIPFNS.mstripTip=function(a){var pid=a[0],k=a[1],nen=a.slice(2).join("|");
 var sp="";try{sp=jOutSum(jCtx(pid),k,2)}catch(e){}
 return nen+(sp?(" · để lại: "+sp):" · chặng này chưa để lại dữ liệu nào")+" - bấm để xem chi tiết"};
function mstripFor(pid,ix){if(!pid)return "";try{var J=jInfo(pid,ix);return mstrip(J.k,J.over,pid)}catch(e){return ""}}
/* Khoảng thời gian một người NẰM Ở một chặng: từ lúc vào chặng đó tới lúc vào chặng kế tiếp
   (chặng hiện tại thì tính tới bây giờ). Không có mốc thì thôi, không bịa. */
function jStageSpan(C,k,dangO){
 var i=JMAIN.indexOf(k);if(i<0)return "";
 var d0=pvnd((JBY[k]&&JBY[k].since(C))||"");if(!d0)return "";
 var d1=null;
 for(var j=i+1;j<JMAIN.length;j++){var d=pvnd((JBY[JMAIN[j]].since(C))||"");if(d&&d.getTime()>=d0.getTime()){d1=d;break}}
 /* Chặng ĐÃ QUA mà không tìm ra mốc chặng kế (dữ liệu ghi lệch ngày) thì THÔI, không nói gì -
    nói "(tới giờ)" cho một chặng người ta rời từ lâu là nói sai, mà nói sai thì thà im. */
 if(!d1&&dangO!==k)return "";
 var ms=(d1?d1.getTime():Date.now())-d0.getTime();if(ms<0)return "";
 var gio=ms/36e5;
 return (gio<1?"dưới 1 giờ":(gio<24?(Math.round(gio)+" giờ"):(Math.round(gio/24)+" ngày")))+(d1?"":" (tới giờ)")}
/* ═══ V9.54 - NGĂN KÉO MỘT CHẶNG. Anh Luân: "bấm vào nút đó thì có hiện ra drawer mô tả lại từ
   chặng đó họ có thông tin gì không, các sản phẩm ở chặng đó như nào?" Bốn câu hỏi một chặng phải
   trả lời được: chặng này ĐỂ LÀM GÌ · đã ĐI QUA CHƯA và lúc nào · để lại SẢN PHẨM gì · giờ LÀM GÌ
   tiếp. Mọi con số hạn đều đi qua slaChip nên bấm bánh răng là sửa được ngay trong ngăn kéo này. */
function jStagePop(pid,k){var J,C;try{J=jInfo(pid);C=J.C}catch(e){return}
 var S=JBY[k];if(!S){toast("Không thấy chặng "+k);return}
 var A=ARCBK[arcOf(k)];
 var cur=JMAIN.indexOf(J.k),me=JMAIN.indexOf(k);
 var tt=(k===J.k)?"đang ở đây":((me>=0&&cur>=0&&me<cur)?"đã qua":(me<0?"nhánh rẽ":"chưa tới"));
 var tcls=(tt==="đang ở đây")?"blue":(tt==="đã qua"?"green":(tt==="nhánh rẽ"?"red":"gray"));
 var luc="";try{luc=String(S.since(C)||"")}catch(e){}
 var sp=jReviewRows(C,k);
 var h='<div class="dcard"><h4><i class="ti '+S.ic+'"></i>'+esc(S.t)+' <span class="chip '+tcls+'" style="margin-left:6px">'+tt+'</span></h4>';
 h+='<div class="notebar" style="margin:0 0 10px"><i class="ti ti-info-circle"></i>'+esc(S.why||"")+'</div>';
 var ct=[["Thuộc chặng lớn","C"+A.n+" · "+esc(A.t)],["Của ai",esc(J.owner||S.owner||"-")]];
 if(luc)ct.push([(tt==="chưa tới"?"Mốc":"Bước vào lúc"),esc(luc.slice(0,16))]);
 var span=jStageSpan(C,k,J.k);if(span)ct.push(["Nằm ở chặng này",esc(span)]);
 if(S.pn)ct.push(["Hạn theo SOP",slaChip(S.pn)]);
 h+=ctxRows(ct);
 /* SẢN PHẨM - phần chính của ngăn kéo này */
 h+='<div class="ph" style="border:0;padding:0 0 6px"><b><i class="ti ti-package" style="margin-right:6px"></i>Sản phẩm chặng này để lại</b></div>';
 if(sp.length)h+='<div class="rvgrid">'+sp.map(function(pr){return '<div class="rvi"><div class="rvk">'+esc(pr[0])+'</div><div class="rvv">'+esc(pr[1])+'</div></div>'}).join("")+'</div>';
 else h+='<div class="empty" style="padding:14px">'+(tt==="chưa tới"?"Chưa tới chặng này nên chưa có sản phẩm nào.":"Chặng này chưa để lại dữ liệu nào trong hồ sơ - có thể mới đi qua mà chưa ai ghi lại.")+'</div>';
 /* việc cần làm theo SOP của chính chặng này (CH4) */
 var na=(JNA[k]||[])[0]||"";
 if(na&&msgText(na))h+='<div class="sopna" style="margin-top:10px"><i class="ti ti-checklist"></i><span><b>Việc cần làm theo SOP · '+esc(na)+':</b> '+esc(msgText(na))+'</span>'+msgEditBtn(na)+'</div>';
 h+='<div class="dact">';
 if(k===J.k&&J.act)h+='<button class="btn primary" onclick="closeModal();runStart(\''+esc(pid)+'\')"><i class="ti '+(J.act.ic||"ti-player-play")+'"></i>'+esc(J.act.lb)+'</button>';
 h+='<button class="btn" onclick="mstripOpen(\''+esc(pid)+'\')"><i class="ti ti-route"></i>Xem cả hành trình</button>'+
  '<button class="btn" onclick="closeModal();jOpen(\''+esc(pid)+'\')"><i class="ti ti-id-badge-2"></i>Mở hồ sơ</button></div></div>';
 openDrawer(C.name+" · "+S.t,h)}
/* V9.18: bấm dải hạt -> drawer "hành trình từng chặng" của đúng người đó
   V9.54: mỗi dòng nay kể luôn SẢN PHẨM và thời gian nằm ở chặng, bấm dòng là mở ngăn kéo chặng đó.
   Anh Luân: "rõ ràng là thiếu cách để chúng ta xem hành trình của 1 học viên một cách tiện dụng". */
function mstripOpen(pid){var J,C;try{J=jInfo(pid);C=J.C}catch(e){return}
 var cur=JMAIN.indexOf(J.k);
 var h='<div class="dcard"><h4><i class="ti ti-route"></i>'+esc(J.name)+'</h4>';
 h+='<div class="notebar" style="margin:0 0 10px"><i class="ti ti-info-circle"></i>Cả vòng đời của một người, chặng nào để lại gì. Bấm một chặng để xem đầy đủ sản phẩm của chặng đó.</div>';
 if(J.S&&J.S.branch)h+='<div class="dnote nbred"><b>Đang ở nhánh rẽ: '+esc(J.S.t)+'.</b> '+esc(J.S.why||"")+'</div>';
 h+='<div class="hvj">';
 JMAIN.forEach(function(k,i){var S=JBY[k];var st=(cur<0)?"":(i<cur?"done":(i===cur?"now":""));
  var when=st?String(S.since(C)||""):"";
  var A=ARCBK[arcOf(k)];
  var sum=st?jOutSum(C,k,2):"";
  var span=st?jStageSpan(C,k,J.k):"";
  h+='<div class="hvjr'+(st?" on":"")+' clk" onclick="jStagePop(\''+esc(pid)+'\',\''+esc(k)+'\')" data-tip="Bấm để xem đầy đủ sản phẩm chặng '+esc(S.t)+'">'+
   '<span class="hvjd"'+(st==="now"?' style="background:'+A.col+';color:#fff"':'')+'><i class="ti '+(st==="done"?"ti-check":S.ic)+'"></i></span>'+
   '<div class="hvjc"><b>'+esc(S.t)+(st==="now"?' <span class="chip blue">đang ở đây</span>':'')+'</b><span>Chặng '+A.n+' · '+esc(A.t)+(span?(' · nằm ở đây '+esc(span)):'')+'</span>'+
   (sum?'<span class="hvjo"><i class="ti ti-package"></i>'+esc(sum)+'</span>':(st?'<span class="hvjo mut"><i class="ti ti-package-off"></i>chưa ghi lại gì ở chặng này</span>':''))+'</div>'+
   '<div class="hvjt">'+(when?esc(when.slice(0,16)):'<span class="mut">-</span>')+'</div></div>'});
 h+='</div>';
 h+='<div class="dact">'+(J.act?'<button class="btn primary" onclick="closeModal();runStart(\''+esc(pid)+'\')"><i class="ti '+((J.act&&J.act.ic)||"ti-player-play")+'"></i>'+esc(J.act?J.act.lb:"Chạy quy trình")+'</button>':'')+
  '<button class="btn" onclick="closeModal();openQuick(\''+esc(pid)+'\')"><i class="ti ti-eye"></i>Xem hồ sơ</button></div></div>';
 openDrawer("Hành trình của "+C.name,h)}
/* ===== V9.15 NODE TANG 3 - sopBlock: BLOCK NGHIEP VU CAN THIET tren moi trang chi tiet =====
   4 dong chuan: Chang (arc + ga + dai hat) / Viec ke / Thoi han / Phu trach
   + canh bao thieu du lieu + cau nhan chuan CH4. btns=false -> khong ve cot nut. */
function sopBlock(J,btns){
 if(!J||!J.S)return "";
 var a=arcOf(J.k),A=ARCBK[a];
 var age=J.ageH==null?"-":(J.ageH<24?Math.round(J.ageH)+" giờ":Math.floor(J.ageH/24)+" ngày");
 var h='<div class="jnext sopb'+(J.over?" over":"")+'">';
 h+='<div class="jnl">';
 h+='<div class="sopr"><span class="soprk">Chặng</span><span class="soprv" style="display:flex;align-items:center;gap:8px;flex-wrap:wrap"><span class="chip" style="background:'+A.col+'14;color:'+A.col+'">C'+A.n+' · '+esc(A.t)+'</span><span class="chip '+J.S.cls+'">'+esc(J.S.t)+'</span>'+mstrip(J.k,J.over)+'</span></div>';
 h+='<div class="sopr"><span class="soprk">Việc kế</span><span class="soprv"><b>'+esc(J.act?J.act.lb:"Không có việc bắt buộc - theo dõi định kỳ")+'</b>'+(J.S.why?'<div class="sopw">'+esc(J.S.why)+'</div>':'')+'</span></div>';
 h+='<div class="sopr"><span class="soprk">Thời hạn</span><span class="soprv">'+(J.sla>0?('Ở bước này đã '+age+' · hạn '+(J.sla<24?Math.round(J.sla)+" giờ":Math.round(J.sla/24)+" ngày")+(J.over?' · <b style="color:var(--red)">QUÁ HẠN</b>':'')):'Không đặt SLA cứng - chăm theo nhịp định kỳ')+'</span></div>';
 h+='<div class="sopr"><span class="soprk">Phụ trách</span><span class="soprv">'+esc(J.owner||J.S.owner||"-")+'</span></div>';
 if(J.miss.length)h+='<div class="jnm"><i class="ti ti-file-alert"></i><b>Thiếu dữ liệu bắt buộc:</b> '+esc(J.miss.join(", "))+' - bổ sung xong mới đi tiếp được.</div>';
 /* V9.29c (anh Luân): trước ghi "Câu nhắn chuẩn SOP" - nghe như câu để GỬI CHO KHÁCH, trong khi
    CH4 là câu NHẮC VIỆC cho nhân viên ("HV đang học đều, không cần làm gì thêm" thì nhắn cho ai?).
    Dùng đúng một chữ với màn Chạy quy trình: "Việc cần làm theo SOP · <mã>". */
 if(J.naMsg)h+='<div class="sopna"><i class="ti ti-checklist"></i><span><b>Việc cần làm theo SOP · '+esc(J.na)+':</b> '+esc(J.naMsg)+'</span>'+msgEditBtn(J.na)+'</div>';
 h+='</div>';
 if(btns!==false)h+='<div class="jnr">'+(btns||('<button class="btn primary" onclick="runStart(\''+esc(J.C.pid)+'\')"><i class="ti ti-player-play"></i>Xử lý theo quy trình</button>'))+'</div>';
 return h+'</div>'}
/* bỏ dấu tiếng Việt để tìm kiếm: gõ "nguyen" vẫn ra "Nguyễn" */
function vnorm(s){s=String(s==null?"":s).toLowerCase();
 if(s.normalize)s=s.normalize("NFD").replace(/[̀-ͯ]/g,"");
 return s.replace(/đ/g,"d")}
/* ===== CHUẨN THÔNG ĐIỆP (CH4) - câu nhắc việc chuẩn của SOP ===== */
function ch4List(){return (DATA.config&&DATA.config.ch4)||[]}
/* V9.29 (mảng 5): câu nhắc in ra màn hình mà không nói lấy từ đâu - muốn sửa phải mò trong CH4.
   msgEdit nhảy thẳng tới đúng câu, enumEdit nhảy tới đúng danh mục CH1. Cùng một ý với slaChip. */
function msgGo(code){window.SETTAB="ch4";window.MSGQ=code||"";go("settings");
 setTimeout(function(){var el=document.querySelector('[data-msg="'+code+'"]');
  if(el&&el.scrollIntoView)el.scrollIntoView({block:"center"})},60)}
/* V9.29b (anh Luân): bỏ chữ "Sửa câu này" - chỉ để BÁNH RĂNG, chú thích hiện khi rê chuột.
   Cùng một ngôn ngữ với slaChip/kpiChip: thấy bánh răng là biết chỗ đó sửa được. */
function msgEditBtn(code){if(!code||!gearOn())return "";
 return '<button class="cfedit" onclick="event.stopPropagation();msgPop(\''+esc(code)+'\')" '+
  'aria-label="Sửa câu nhắc '+esc(code)+'" '+
  'data-tip="Câu nhắc '+esc(code)+' · lấy từ CH4 - bấm để sửa ngay tại đây"><i class="ti ti-settings"></i></button>'}
function enumGo(name){window.SETTAB="ch1";window.ENUMQ=name||"";go("settings")}
function enumEditBtn(name){if(!name)return "";
 return '<button class="cfedit" onclick="event.stopPropagation();enumPop(\''+esc(name)+'\')" '+
  'aria-label="Sửa danh mục '+esc(name)+'" '+
  'data-tip="Danh mục '+esc(name)+' · lấy từ CH1 - bấm để sửa ngay tại đây"><i class="ti ti-settings"></i></button>'}
function ch4Get(code){if(!code)return null;var a=ch4List();for(var i=0;i<a.length;i++)if(a[i].code===code)return a[i];return null}
/* V9.29 (anh Luân): CỘT "KHI NÀO HIỆN" cũng phải lấy số từ cấu hình, không cắm cứng.
   Một hàm thay chỗ trống dùng chung cho cả câu mẫu lẫn câu mô tả - hai chỗ mà hai cách thay
   thì sớm muộn cũng nói hai con số khác nhau. */
function msgFill(txt,params){var t=String(txt||"");
 (params||[]).forEach(function(pn,i){var v=paramOf(pn,null);
  if(v==null){var sv=paramStr(pn,"");v=sv!==""?sv:null}
  t=t.replace(new RegExp("\\{"+(i+1)+"\\}","g"),(v==null?"?":String(v)))});
 return t}
function msgText(code){var m=ch4Get(code);if(!m)return "";return msgFill(m.tmpl,m.params)}
function msgWhen(code){var m=ch4Get(code);if(!m)return "";return msgFill(m.when,m.params)}
/* chặng -> mã thông điệp CH4 [thường, khi quá hạn]; áp chuẩn SOP vào từng bước hành trình */
var JNA={new:["NA050","NA049"],contacted:["NA052","NA048"],test_booked:["",""],test_grading:["NA055","NA054"],
 test_done:["","NA001"],consult:["NA004","NA003"],enrolled:["NA006","NA007"],paid:["","NA063"],
 onboarding:["NA062","NA010"],learning:["NA018",""],ending:["",""],reenroll:["",""],alumni:["",""],
 no_contact:["","NA047"],lost:["NA053","NA053"],paused:["",""],cancelled:["NA059","NA059"]};
function jNaCode(k,over){var p=JNA[k];if(!p)return "";return (over&&p[1])?p[1]:(p[0]||p[1]||"")}

/* ===== CH4 SỐNG: chọn mẫu thông điệp THEO TÌNH HUỐNG THẬT của từng bản ghi =====
   Trước đây cột next_action là chữ TĨNH nằm sẵn trong dữ liệu - sửa trạng thái thì
   nó không đổi, và không mang được số SLA thật từ CH2. Nay tra thẳng CH4. */
function hSince(v){var d=pvnd(v);return d?(Date.now()-d.getTime())/3600000:null}
function naFor(sheet,r){
 if(!r)return "";
 var C=function(f){return ecode(r[f])};
 var P=function(k,dv){return paramOf(k,dv)};
 if(sheet==="DL02"){                                   /* khách tiềm năng */
  var h=hSince(r.lead_created_time),f=hSince(r.first_call_time),cc=num(r.contact_count);
  if(isc(r.lead_status,"converted","rejected","no_response","unreachable"))return "NA053";
  if(!r.first_call_time){var lim=P("slaLRT_minutes",15);
   if(h!=null&&h*60>P("slaLeadReassign_hours",4)*60)return "NA046";   /* quá lâu -> giao lại NV khác */
   return (h!=null&&h*60>lim)?"NA049":"NA050"}
  if(cc>=P("thresholdContacted_attempts",5))return "NA047";
  var fu=pvnd(r.next_followup_time);
  if(fu){return (fu.getTime()<Date.now())?"NA051":"NA052"}
  return (f!=null&&f/24>P("thresholdContacted_days",7))?"NA048":"NA052"}
 if(sheet==="DL03"){                                   /* test đầu vào */
  if(num(r.overall_score)>0){                       /* đã có điểm */
   if(isc(r.post_test_status,"consulted"))return "NA002";
   if(!String(r.post_test_status||"").trim())return "NA085";        /* chưa chuyển trạng thái sau test */
   if(!rows("DL04").some(function(c){return String(c.lead_id||"")===String(r.lead_id||"")}))return "NA086";
   var hr=hSince(r.result_time||r.test_date);
   return (hr!=null&&hr>P("slaCVT_hours",24))?"NA001":"NA056"}
  var td=pvnd(r.test_date);
  if(td&&td.getTime()<Date.now()){var hh=hSince(r.test_date);
   return (hh!=null&&hh>P("slaGLA_hours",24))?"NA054":"NA055"}    /* quá hạn chấm / còn trong hạn */
  return "NA055"}
 if(sheet==="DL04"){                                   /* tư vấn */
  if(isc(r.conversion_status,"dropped"))return "NA058";
  if(isc(r.conversion_status,"confirmed_with_deposit"))return "NA057";
  var hv=hSince(r.consultation_time);
  return (hv!=null&&hv/24>P("slaFollowup_grace_days",3))?"NA003":"NA004"}
 if(sheet==="DL06"){                                   /* đăng ký & học phí */
  if(isc(r.enrollment_status,"cancelled"))return "NA008";           /* hủy -> kiểm tra hoàn tiền */
  if(num(r.discount_amount)>0&&!String(r.discount_approved_by||"").trim())return "NA061";  /* CK vượt mức, chờ duyệt */
  var rem=num(r.remaining_amount);
  /* V9.41 - SOP tách hai trạng thái "đã đóng đủ": NA088 là ĐÃ ĐỦ TIỀN mà chưa mở onboarding
     (còn việc phải làm), NA009 là đã đủ và đã xong. Trước đây app trả cùng một mã cho cả hai
     nên hồ sơ đóng đủ tiền rồi nằm im không ai biết phải mở bước sau. */
  if(rem<=0){
   var _ob=rows("DL08").some(function(o){return String(o.enrollment_id||"")===String(r.enrollment_id||"")});
   return _ob?"NA009":"NA088"}
  var hd=hSince(r.enrollment_time);
  if(isc(r.enrollment_status,"pending")){
   /* NA087: đã đủ cọc tối thiểu mà đơn còn treo ở "chờ" - phải chuyển sang xác nhận và mở
      onboarding, không thì em đã đóng tiền mà chưa được xếp lớp. */
   var _coc=num(paramOf("thresholdDeposit_minimum",0));
   if(_coc>0&&num(r.paid_amount)>=_coc)return "NA087";
   /* NA060: chờ quá lâu - cân nhắc hủy để dọn dữ liệu, không để đơn ma nằm mãi trong phễu */
   if(hd!=null&&hd>P("slaENR_stale_hours",P("slaENR_pending_hours",24)*7))return "NA060";
   return (hd!=null&&hd>P("slaENR_pending_hours",24))?"NA005":"NA006"}
  return (hd!=null&&hd>P("slaPayment_hours",48))?"NA007":"NA006"}
 if(sheet==="DL08"){                                   /* xếp lớp & onboarding */
  /* V9.41 - SOP tách: NA089 là đã xác nhận lớp VÀ hoàn tất onboarding nhưng học viên chưa được
     chuyển sang "đang học"; NA012 là đã xong trọn vẹn. Không tách thì bước cuối bị nuốt. */
  if(isc(r.onboarding_status,"completed")){
   var _s9=find("DL09","student_id",r.student_id);
   if(_s9&&!/active|studying/.test(ecode(_s9.student_status))&&!stuGone(_s9))return "NA089";
   return "NA012"}
  if(!String(r.class_id||"").trim()){var hz=hSince(r.assigned_at);
   return (hz!=null&&hz>P("slaPLR48_hours",48))?"NA063":"NA013"}
  if(!String(r.class_info_sent_at||"").trim()){var hi=hSince(r.assigned_at);
   return (hi!=null&&hi>P("slaClassInfoZalo_hours",24))?"NA062":"NA013"}
  if(!isc(r.class_confirmation_status,"confirmed"))return "NA090";
  var ha=hSince(r.confirmation_time);
  return (ha!=null&&ha>P("slaOBT_hours",48))?"NA010":"NA011"}
 /* ===== V9.41 - BA BẢNG SOP MÔ TẢ TRIGGER MÀ naFor CHƯA HỀ CÓ NHÁNH =================
    Đo bằng máy: sổ trigger HD3 của SOP có 93 tình huống, app sinh ra 50. Gốc của 21 chỗ hụt
    nằm ở đây - naFor không có nhánh nào cho DL09 (học viên), DL11 (buổi học), DL12 (điểm danh),
    nên mọi mã nhắc việc SOP viết cho ba bảng đó chưa bao giờ chạy.
    Riêng DL09: SOP phân NĂM MỨC can thiệp khác nhau, không phải một mức "nguy cơ" chung. Trộn
    năm mức làm một là mất đúng phần giá trị - vì mỗi mức SOP chỉ định một hành động khác hẳn:
    họp 4 bên / họp 3 bên trong 24h / đặt buổi WOW / gọi trong 24-48h. */
 if(sheet==="DL09"){                                   /* học viên */
  if(/dropped|transferred|graduated/.test(C("student_status")))return "";
  var _cc=C("attendance_progress_status"),_ht=C("academic_progress_status");
  var _A=riskAuto(r.student_id);
  /* mức nặng nhất trước - một học viên chỉ nhận MỘT việc, không réo năm lần */
  if(_cc==="off_track"&&_ht==="off_track")return "NA014";   /* yếu cả hai - họp 4 bên gấp */
  if(_ht==="off_track")return "NA015";                      /* học thuật rớt lộ trình - họp 3 bên 24h */
  if(_cc==="off_track")return "NA016";                      /* chuyên cần rớt lộ trình - họp 3 bên */
  if(_ht==="at_risk")return "NA066";                        /* học thuật at-risk - đặt WOW kèm */
  if(_cc==="at_risk")return "NA017";                        /* chuyên cần at-risk - gọi trong 24-48h */
  /* máy thấy vượt ngưỡng mà người chưa gắn cờ - SOP tách riêng hai mã này */
  if(!ignRisk(r)&&_A.att)return "NA064";
  if(!ignRisk(r)&&_A.aca)return "NA065";
  var _im=hSince(r.last_learning_activity_time);
  if(_im!=null&&_im/24>P("slaActivity_inactive_days",7))return "NA067";
  return "NA018"}    /* đang học đều và ổn định - SOP muốn cột việc cần làm nói RÕ điều đó */
 if(sheet==="DL11"){                                   /* buổi học */
  if(isc(r.session_status,"cancelled"))return "NA023";      /* hủy - lên lịch bù */
  if(isc(r.session_status,"rescheduled"))return "NA024";    /* đã dời - cập nhật lại lịch */
  if(isc(r.session_status,"in_progress"))return "NA020";    /* đang diễn ra */
  if(isc(r.session_status,"completed")){
   var _st=bhState(r);
   if(_st.note)return "NA022";                              /* đã xong, đã ghi nhận xét */
   return "NA021"}                                          /* đã xong, chưa ghi nhận xét */
  /* SOP: NA019 = buổi sắp tới, giáo viên chuẩn bị giáo án. Trước đây app dùng nhầm mã này cho
     "đã dạy xong còn trong hạn ghi nhận xét" - sai nghĩa, và làm tình huống chuẩn bị giáo án
     biến mất khỏi mọi màn. */
  return "NA019"}
 if(sheet==="DL12"){                                   /* điểm danh */
  if(isc(r.attendance_status,"no_show")){
   if(/unexcused/.test(C("absence_type"))){
    var _ss=find("DL11","session_id",r.session_id);
    var _h=_ss?hSince(_ss.session_date):null;
    if(String(r.note||"").trim())return "NA025";
    return (_h!=null&&_h>P("slaAbsenceCall_hours",24))?"NA070":"NA025"}
   return "NA026"}                                          /* vắng có phép - đề xuất WOW học bù */
  if(isc(r.attendance_status,"late"))return "NA027";
  if(isc(r.attendance_status,"on_time"))return "NA028";
  return ""}
 if(sheet==="DL13"){                                   /* bài tập */
  if(hwGraded(r))return "NA030";
  if(hwSubmitted(r)){var hs=hSince(r.homework_submitted_time);
   return (hs!=null&&hs>P("slaHomeworkGrading_hours",48))?"NA071":"NA072"}
  if(hwMissing(r))return "NA029";
  var du=pvnd(r.homework_due_date);
  return (du&&du.getTime()<Date.now())?"NA029":"NA073"}
 if(sheet==="DL14"){                                   /* buổi WOW */
  if(isc(r.wow_status,"cancelled"))return "NA077";
  if(isc(r.wow_status,"no_show"))return "NA035";
  if(isc(r.wow_status,"completed")){
   if(!String(r.wow_content_note||"").trim()){var hw2=hSince(r.wow_session_date);
    return (hw2!=null&&hw2>P("slaWowNote_hours",24))?"NA075":"NA076"}
   if(!String(r.wow_outcome||"").trim())return "NA034";
   if(!/^(y|c|t|1)/i.test(String(r.quota_deducted||"")))return "NA074";
   return "NA034"}
  var sd=pvnd(r.wow_session_date);
  if(sd&&sd.getTime()<Date.now())return "NA032";
  if(!isc(r.wow_status,"confirmed"))return "NA031";
  return "NA033"}
 if(sheet==="DL15"){                                   /* khảo sát */
  if(String(r.submitted_date||"").trim()){
   if(num(r.satisfaction_score)&&num(r.satisfaction_score)<=3)return "NA079";   /* cần theo dõi thêm */
   var hsv=hSince(r.submitted_date);
   return (hsv!=null&&hsv>P("slaSurveyReport_hours",48))?"NA078":"NA037"}
  return "NA036"}
 if(sheet==="DL16"){                                   /* phản hồi */
  if(isc(r.feedback_status,"resolved"))return "NA094";
  if(isc(r.feedback_type,"negative"))return "NA093";
  var hf=hSince(r.feedback_time);
  return (hf!=null&&hf>P("slaFB_classify_hours",24))?"NA091":"NA092"}
 if(sheet==="DL17"){                                   /* khiếu nại */
  if(isc(r.complaint_status,"resolved"))return "NA041";
  if(String(r.escalated_to||"").trim())return "NA040";
  if(!String(r.assigned_handler||"").trim())return "NA081";
  var hc=hSince(r.complaint_time),sev=C("complaint_severity");
  if(sev==="high"||sev==="critical")return (hc!=null&&hc>P("slaKN_high_hours",4))?"NA038":"NA081";
  if(sev==="medium")return (hc!=null&&hc>P("slaKN_medium_hours",24))?"NA039":"NA081";
  return (hc!=null&&hc>P("slaKN_low_hours",72))?"NA080":"NA081"}
 if(sheet==="DL18"){                                   /* kết thúc & tái đăng ký */
  if(isc(r.re_enrollment_status,"confirmed_with_deposit"))return "NA044";
  if(isc(r.re_enrollment_status,"rejected"))return "NA084";
  if(isc(r.student_status,"dropped"))return "NA043";
  if(!num(r.final_test_score))return "NA082";
  if(isc(r.re_enrollment_status,"interested"))return "NA083";
  var he=hSince(r.course_completion_time);
  return (he!=null&&he>P("slaReenroll_days",3)*24)?"NA042":"NA045"}
 return ""}
/* Thông điệp hiển thị: ưu tiên CH4 sống, không có thì mới dùng chữ lưu sẵn */
function naLive(sheet,r){var c=naFor(sheet,r);var t=c?msgText(c):"";
 return t||String((r&&r.next_action)||"")}
function jStageOf(C){
 var e=C.enrMain,ob=C.obMain,ce=C.ceMain,S=C.S,L=C.L;
 var stCode=S?ecode(S.student_status):"";
 if(stCode==="dropped"||stCode==="transferred")return "paused";   /* bỏ học/bảo lưu ưu tiên hơn mọi chặng khác */
 /* HV học NHIỀU KHÓA: hồ sơ kết thúc của khóa CŨ (đã nối sang khóa mới, hoặc đang có lớp khác)
    không được giam hành trình ở alumni - xét theo khóa ĐANG HỌC */
 if(ce&&(String(ce.next_enrollment_id||"").trim()||(ob&&ob.class_id&&ce.class_id&&ob.class_id!==ce.class_id)))ce=null;
 if(ce){
  if(/confirmed/.test(ecode(ce.re_enrollment_status)))return "alumni";
  if(String(ce.final_test_score||"").trim()||/completed/.test(ecode(ce.student_status)))return /not_contacted|contacted|interested/.test(ecode(ce.re_enrollment_status))?"reenroll":"alumni";
  return "ending"}
 if(ob){
  if(/completed/.test(ecode(ob.onboarding_status)))return "learning";
  return "onboarding"}
 if(C.enrLive.length){
  var rem=num(C.enrMain.remaining_amount);
  if(rem<=0&&C.pays.length)return "paid";
  return "enrolled"}
 if(C.enr.length&&!C.enrLive.length)return "cancelled";
 if(C.cons.length){
  var lastc=C.cons[C.cons.length-1];
  if(isc(lastc.conversion_status,"dropped")&&!C.enrLive.length)return "lost";
  return "consult"}
 var t=C.testMain;
 if(t){
  if(isc(t.test_status,"graded"))return "test_done";
  if(isc(t.test_attendance_status,"on_time","late"))return "test_grading";
  if(isc(t.booking_status,"booked"))return "test_booked";
 }
 var ls=L?ecode(L.lead_status):"";
 if(ls==="rejected"||ls==="unreachable")return "lost";
 if(L&&failStreak(L.lead_id)>=paramOf("attemptsNoResponse",3))return "no_contact";
 if(C.tps.length||ls==="contacted"||ls==="considering"||ls==="no_response")return "contacted";
 return "new"}
function jInfo(pid,ix){var C=jCtx(pid,ix);var k=jStageOf(C);var S=JBY[k]||JBY.new;
 var since=S.since(C)||(C.L&&C.L.lead_created_time)||"";
 var ageH=hoursSince(since);var lim=S.sla();
 var over=(lim>0&&ageH!=null&&ageH>lim);
 var miss=S.need(C)||[];
 var act=S.act(C);
 var naCode=jNaCode(k,over);var naMsg=msgText(naCode);
 return {C:C,k:k,S:S,since:since,ageH:ageH,sla:lim,over:over,miss:miss,act:act,na:naCode,naMsg:naMsg,
  name:C.name,phone:C.phone,owner:C.ownerName||C.owner}}
function jAll(){var ix=jIndex(),out=[],seen={};
 rows("DL02").forEach(function(L){out.push(jInfo(L.lead_id,ix));seen[L.lead_id]=1});
 rows("DL09").forEach(function(S){var has=false;(ix.enrS[S.student_id]||[]).forEach(function(e){if(e.lead_id&&seen[e.lead_id])has=true});
  if(!has)out.push(jInfo(S.student_id,ix))});
 /* CỔ CHAI 2 (V9.22): lọc PHẠM VI ở đây - jIndex vẫn chạy trên dữ liệu đầy đủ (không thì sai cột *_name
    và sai % chuyển đổi của phễu); chỉ lọc mảng KẾT QUẢ nên mọi màn hạ nguồn (Trang bắt đầu, Bảng chặng,
    4 trang Chặng, jTasks -> chuông -> bong bóng) tự đúng phạm vi. */
 if(CURSTAFF&&dsCfg().on)out=out.filter(function(J){return canPid(J.C.pid)});
 return out}
/* --- HÀNH ĐỘNG: chặn khi thiếu dữ liệu bắt buộc --- */
function jGuard(pid,fn,arg){var J=jInfo(pid);
 if(J.miss.length){toast("Thiếu dữ liệu bắt buộc: "+J.miss.join(", ")+". Hãy bổ sung trước khi đi tiếp.");jOpen(pid);return false}
 return true}
