/* ==========================================================================
   CHẠY QUY TRÌNH (RUN) - dắt tay nhân viên đi từng màn theo lộ trình.
   Mỗi chặng có MỘT màn thao tác gọn: chỉ hỏi đúng thứ cần cho bước đó,
   lưu xong tự nhảy sang màn kế tiếp. Có hàng đợi để làm liên tục nhiều người.
   ========================================================================== */
var JIDK={},JIDP={};
function jIdInit(){for(var k in LISTCFG){var c=LISTCFG[k];if(c&&c.code&&c.cols&&c.cols[0]){JIDK[c.code]=c.cols[0][0];if(c.idp)JIDP[c.code]=c.idp}}}
function jSaveRow(code,o,cb){jIdInit();
 var idk=JIDK[code]||"id";
 function done(id){o[idk]=id;rows(code).unshift(o);
  logAct("Tạo mới",code,id,{},"Tạo dòng mới"+(o.full_name?(" - "+o.full_name):""),{kind:"add",sau:JSON.stringify(o)});
  if(cb)cb(id)}
 if(SVR){google.script.run.withSuccessHandler(function(r){if(!r||!r.ok){toast("Lỗi ghi: "+((r&&r.error)||""));return}done(r.id)})
  .withFailureHandler(function(e){toast("Lỗi kết nối: "+e.message)}).apiSave(code,o)}
 else{done((JIDP[code]||(code+"-"))+seqNo(code,idk))}}
function jUpdRow(code,id,vals,cb){jIdInit();var idk=JIDK[code]||"id";var r=find(code,idk,id);
 var _b=logSnap(r);
 if(r)for(var k in vals)r[k]=vals[k];
 logAct("Cập nhật",code,id,logDiff(_b,logSnap(r)));
 if(SVR)google.script.run.withSuccessHandler(function(){if(cb)cb()}).withFailureHandler(function(){if(cb)cb()}).apiUpdate(code,id,vals);
 else if(cb)cb()}
/* --- form gọn cho từng bước --- */
function rfHTML(fs,C){var h='<div class="rform">';
 fs.forEach(function(f){var id="r_"+f[0],lb=f[1],ty=f[2]||"text",op=f[3],req=f[4],dv=(f[5]!==undefined?f[5]:"");
  if(ty==="attach"){h+=attachBox(f[0],lb);return}
  var full=(ty==="ta"||ty==="seg")?" full":"";
  h+='<div class="fld'+full+'"><label>'+esc(lb)+(req?' <i>*</i>':'')+'</label>';
  if(ty==="ta")h+='<textarea id="'+id+'" rows="3">'+esc(dv)+'</textarea>';
  else if(ty==="num")h+='<input id="'+id+'" type="number" value="'+esc(dv)+'">';
  else if(ty==="dt"){h+='<input id="'+id+'" type="datetime-local" value="'+esc(toISOdt(dv))+'">';if(f[0]==="next_followup_time")h+=dtQuickHTML(id)}
  else if(ty==="date")h+='<input id="'+id+'" type="date" value="'+esc(toISOdt(dv,1))+'">';
  else if(ty==="enum")h+='<select id="'+id+'">'+enumOpts(op,dv)+'</select>';
  else if(ty==="cres")h+='<select id="'+id+'">'+cresOpts(dv||"connected")+'</select>';
  else if(ty==="sel")h+='<select id="'+id+'">'+op+'</select>';
  else if(ty==="seg"){h+='<div class="rseg">'+op.map(function(o,i){return '<button type="button" class="rsb'+(i===0?" on":"")+'" data-v="'+esc(o[0])+'" onclick="rfSeg(this)"><i class="ti '+o[2]+'"></i>'+esc(o[1])+'</button>'}).join("")+'<input type="hidden" id="'+id+'" value="'+esc(op[0][0])+'"></div>'}
  else h+='<input id="'+id+'" value="'+esc(dv)+'"'+(op?' placeholder="'+esc(op)+'"':'')+'>';
  if(f[6])h+='<div class="fhint">'+esc(f[6])+'</div>';
  h+='</div>'});
 return h+'</div>'}
function rfSeg(b){var box=b.parentNode;[].forEach.call(box.querySelectorAll(".rsb"),function(x){x.classList.remove("on")});
 b.classList.add("on");var inp=box.querySelector("input");if(inp)inp.value=b.getAttribute("data-v")}
/* ===== V9.27 NUT HEN NHANH (anh Luân: "làm vài nút thường dùng, kèm giờ vào") =====
   Ô nhập là NGÀY + GIỜ nên mọi nút đều phải chốt luôn giờ - không có nút nào để trống giờ.
   Nhãn và giá trị dùng CHUNG một hàm dựng, nên nhãn không bao giờ nói một đằng đặt một nẻo.
   Nút nào đã trôi qua thì tự ẩn: 6h tối không còn thấy "Chiều nay 15h" nữa. */
function dtAt(d,h,m){d.setHours(h,m||0,0,0);return d}
function dtDay(n,h){return dtAt(new Date(Date.now()+n*864e5),h)}
function dtDow(dow,h){var add=(dow-new Date().getDay()+7)%7||7;return dtDay(add,h)}
function dtHHMM(d){return ("0"+d.getHours()).slice(-2)+":"+("0"+d.getMinutes()).slice(-2)}
function dtDMY(d){return ("0"+d.getDate()).slice(-2)+"/"+("0"+(d.getMonth()+1)).slice(-2)}
/* V9.29o (mảng 5): GIỜ HẸN GỢI Ý cũng là thói quen của trung tâm, không phải hằng số của app.
   Trung tâm mở cửa 8h hay 9h30, ca tối 19h hay 20h - đổi ở cấu hình, mọi nút đổi theo và NHÃN
   trên nút cũng tự đổi (nhãn sinh từ chính con số, không gõ tay lần hai). */
function apptH(k,fb){return num(paramOf(k,fb))||fb}
var DTQUICK=[
 ["h2", function(){var d=new Date(Date.now()+apptH("apptSoon_hours",2)*36e5);d.setSeconds(0,0);d.setMinutes(d.getMinutes()<=30?30:60);return d},
        function(d){return apptH("apptSoon_hours",2)+" tiếng nữa · "+dtHHMM(d)}],
 ["t15",function(){return dtAt(new Date(),apptH("apptAfternoon_hour",15))}, function(){return "Chiều nay "+apptH("apptAfternoon_hour",15)+"h"}],
 ["t19",function(){return dtAt(new Date(),apptH("apptEvening_hour",19))},   function(){return "Tối nay "+apptH("apptEvening_hour",19)+"h"}],
 ["m9", function(){return dtDay(1,apptH("apptMorning_hour",9))},  function(){return "Mai "+apptH("apptMorning_hour",9)+"h"}],
 ["m14",function(){return dtDay(1,apptH("apptNoon_hour",14))},    function(){return "Mai "+apptH("apptNoon_hour",14)+"h"}],
 ["m19",function(){return dtDay(1,apptH("apptEvening_hour",19))}, function(){return "Mai "+apptH("apptEvening_hour",19)+"h"}],
 ["d2", function(){return dtDay(2,apptH("apptMorning_hour",9))},  function(){return "Ngày kia "+apptH("apptMorning_hour",9)+"h"}],
 ["sat",function(){return dtDow(6,apptH("apptMorning_hour",9))},  function(){return "Thứ 7 "+apptH("apptMorning_hour",9)+"h"}],
 ["w9", function(){return dtDay(7,apptH("apptMorning_hour",9))},  function(){return "Tuần sau "+apptH("apptMorning_hour",9)+"h"}],
 ["w2", function(){return dtDay(14,apptH("apptMorning_hour",9))}, function(){return "2 tuần nữa "+apptH("apptMorning_hour",9)+"h"}]];
var DTQBK={};DTQUICK.forEach(function(r){DTQBK[r[0]]=r});
function dtVal(d){return d.getFullYear()+"-"+("0"+(d.getMonth()+1)).slice(-2)+"-"+("0"+d.getDate()).slice(-2)+"T"+dtHHMM(d)}
function dtPreset(id,kind){var r=DTQBK[kind];if(!r)return;
 var e=document.getElementById(id);if(e)e.value=dtVal(r[1]());
 /* bấm nút nào thì nút đó sáng lên, biết mình vừa chọn cái gì */
 try{var box=e&&e.parentNode&&e.parentNode.querySelector(".dtq");
  if(box)[].forEach.call(box.querySelectorAll(".pill"),function(b){b.classList.toggle("on",b.getAttribute("data-q")===kind)})}catch(x){}}
function dtQuickHTML(id){var now=Date.now();
 var items=DTQUICK.filter(function(r){return r[1]().getTime()>now+6e4});
 return '<div class="dtq">'+items.map(function(r){var d=r[1]();
  return '<button type="button" class="pill" data-q="'+r[0]+'" data-tip="Đặt thành '+esc(dtDMY(d)+" "+dtHHMM(d))+'" onclick="dtPreset(\''+id+'\',\''+r[0]+'\')">'+esc(r[2](d))+'</button>'}).join("")+'</div>'}
function rfV(k){var e=document.getElementById("r_"+k);if(!e)return "";return normDT(k,String(e.value||"").trim())}
function rfNeed(fs){var m=[];fs.forEach(function(f){if(f[4]&&!rfV(f[0]))m.push(f[1])});return m}
