 h+='<div class="settabs" data-tour="settabs">';
 var stabs=setTabs();
 var rsS=SCOPE();if(rsS.tabs&&rsS.tabs.settings)stabs=stabs.filter(function(t){return rsS.tabs.settings.indexOf(t[0])>=0});
