/* ---- (c) TỰ ĐẶT BUỔI WOW 1-1 ---- */
function hvWowAsk(){
 var h='<div class="dcard"><h4><i class="ti ti-star"></i>Đặt buổi WOW 1-1</h4>';
 h+='<div class="notebar" style="margin:0 0 10px"><i class="ti ti-info-circle"></i>Buổi kèm riêng đã nằm trong gói học của bạn. Chọn kỹ năng yếu nhất và khung giờ - trung tâm xác nhận lại giảng viên và giờ chính thức.</div>';
 /* danh sách kỹ năng lấy NGUYÊN VĂN từ danh mục CH1, không gõ tay 4 chuỗi ở đây */
 h+='<div class="fld"><label>Kỹ năng muốn kèm <i>*</i></label><select id="hvw_skill">'+enumOpts("enum_homework_skill")+'</select></div>';
 h+='<div class="fld"><label>Ngày mong muốn <i>*</i></label><input id="hvw_date" type="date" min="'+isoDay(1)+'" value="'+isoDay(1)+'"><div class="fhint">Mặc định là ngày mai - chọn xa hơn nếu bạn bận.</div></div>';
 h+='<div class="fld full"><label>Khung giờ mong muốn</label><input id="hvw_gio" placeholder="vd: sau 19h các ngày trong tuần"></div>';
 h+='<div class="fld full"><label>Bạn muốn tập trung vào phần nào</label><textarea id="hvw_focus" rows="2" placeholder="vd: em hay bí ý ở Speaking part 2"></textarea></div>';
 h+='<div class="dact"><button class="btn primary" onclick="hvWowSave()"><i class="ti ti-send"></i>Gửi yêu cầu đặt buổi</button>'+
  '<button class="btn" onclick="closeModal()">Hủy</button></div></div>';
 openDrawer("Đặt buổi WOW 1-1",h)}
function hvWowSave(){
 if(!actGuard("hvWow"))return;
 var S=hvMe();if(!S){toast("Chưa xác định được hồ sơ của bạn.");return}
 var d=(fldV("hvw_date")||"").trim();if(!d){toast("Chọn ngày bạn muốn học.");return}
 var when=fromISOdt(d);
 if(pvnd(when)&&pvnd(when).getTime()<hvT0()){toast("Ngày bạn chọn đã qua - chọn ngày khác nhé.");return}
 var left=num(S.wow_quota_remaining);
 if(left<=0){toast("Bạn đã dùng hết lượt WOW của khóa"+(hvHotline()?(" - gọi "+hvHotline()+" nếu cần thêm."):"."),4600);return}
 var _pend=rows("DL14").filter(function(x){return String(x.student_id||"")===S.student_id&&
  isc(x.wow_status,"booked")&&!String(x.staff_id||"").trim()}).length;
 if(_pend>=num(paramOf("wowPendingMax_perStudent",1))){
  toast("Bạn đang có một buổi WOW chờ trung tâm xác nhận. Chờ buổi đó chốt giờ rồi đặt tiếp nhé.",4600);return}
 var w={wow_id:"WOW-"+seqNo("DL14","wow_id"),student_id:S.student_id,student_name:S.full_name,
  booking_date:nowStr(),wow_session_date:when,
  wow_session_type:eFull("enum_wow_session_type","self_booked"),
  wow_booked_by:eFull("enum_wow_booked_by","student"),
  wow_skill:fldV("hvw_skill"),wow_content_focus:(fldV("hvw_focus")||"").trim(),
  staff_id:"",staff_name:"",wow_status:eFull("enum_wow_status","booked"),
  wow_content_note:"",wow_outcome:"",wow_no_show_reason:"",
  quota_deducted:"no",   /* CHƯA dạy thì CHƯA trừ quota - trừ lúc đặt là trừ oan nếu buổi bị hủy */
  sla_content_note_24h:"",notes:"Học viên tự đặt qua cổng"+((fldV("hvw_gio")||"").trim()?" · khung giờ mong muốn: "+(fldV("hvw_gio")||"").trim():""),
  next_action:"Xác nhận giảng viên và giờ chính thức với học viên."};
 DL.DL14=DL.DL14||[];DL.DL14.unshift(w);
 if(SVR)try{google.script.run.apiSave("DL14",w)}catch(e){}
 hvReq("Học viên tự đặt buổi WOW 1-1",
  "Kỹ năng: "+w.wow_skill+"\nNgày mong muốn: "+when+((fldV("hvw_gio")||"").trim()?"\nKhung giờ: "+(fldV("hvw_gio")||"").trim():"")+
  (w.wow_content_focus?"\nMuốn tập trung: "+w.wow_content_focus:"")+"\nMã buổi: "+w.wow_id,
  "hocvu",["wow",w.wow_id,"Buổi WOW "+w.wow_skill]);
 persistSoon();closeModal();
 toast("Đã gửi yêu cầu đặt buổi WOW. Trung tâm sẽ xác nhận giảng viên và giờ chính thức.",4600);
 hvReRender()}

/* ---- (h) BÁO ĐÃ CHUYỂN KHOẢN ---- */
/* Đơn đóng MỘT LẦN (25/90 đơn) không có bảng đợt để vẽ - vẫn phải cho học viên biết ngày và
   số tiền của lần đóng tiếp theo, đọc từ DL06.next_payment_due. */
function hvDueOne(enr,rem){
 if(!enr||!enr.enrollment_id)return "";
 if(rem<=0)return '<div class="hvschd"><div class="hvschh"><i class="ti ti-circle-check" style="color:var(--green)"></i>'+
  '<b>Bạn đã đóng đủ học phí khóa này</b><span class="mut">không còn đợt nào phải đóng</span></div></div>';
 var due=String(enr.next_payment_due||"").trim();
 var rd=paramOf("installmentRemind_days",3),ld=paramOf("installmentLate_days",5);
 var d=due?pvnd(due):null;
 var days=d?Math.round((d.getTime()-hvT0())/864e5):null;
 var cls=(days==null)?"":(days<-ld?"late":(days<0?"due":(days<=rd?"soon":"")));
 var say=(days==null)?"trung tâm chưa chốt ngày":(days<0?("quá hạn "+Math.abs(days)+" ngày"):
  (days===0?"đến hạn HÔM NAY":("còn "+days+" ngày")));
 var h='<div class="hvschd"><div class="hvschh"><i class="ti ti-calendar-dollar"></i>'+
  '<b>Lần đóng tiếp theo</b><span class="mut">trung tâm nhắc bạn trước hạn '+rd+' ngày</span></div>'+
  '<div class="hvschr '+cls+'"><span class="hvschn">Còn phải đóng</span>'+
  '<span class="hvschd2">'+esc(due||"chưa hẹn ngày")+'</span>'+
  '<span class="hvscha"><b>'+vnd(rem)+'</b></span>'+
  '<span class="hvschs">'+esc(say)+'</span></div>';
 if(!due)h+='<div class="hvreqc" style="margin:6px 14px 0">Trung tâm chưa chốt ngày cho lần đóng tiếp theo. '+
  'Bạn bấm <b>Tôi đã chuyển khoản</b> nếu đã chuyển, hoặc gọi trung tâm để hẹn ngày.</div>';
 return h+'</div>'}
/* V9.48 - anh Luân: *"cái tôi đã chuyển khoản này, cho người ta chọn đợt luôn nhé, nhập số tiền
   và đính kèm được ảnh/file nha"*. Đúng ba chỗ thiếu:
   1. Bản cũ TỰ ĐOÁN đợt (lấy đợt chưa đóng nhỏ nhất) rồi chỉ ghi một dòng chữ. Em đóng đợt 3
      trước đợt 2 thì kế toán đối soát nhầm đợt - mà đây là tiền.
   2. Số tiền có sẵn nhưng không đổi được theo đợt vừa chọn.
   3. KHÔNG có chỗ đính ảnh biên lai - thứ kế toán cần nhất để đối soát. Thành phần `attachBox`
      đã có sẵn và các cửa ghi nội bộ đều dùng, riêng cổng học viên thì bỏ quên. */
function hvPnDot(eid){
 return rows("DL06b").filter(function(x){return String(x.enrollment_id||"")===eid&&!isc(x.status,"paid")})
  .sort(function(a,b){return num(a.installment_no)-num(b.installment_no)})}
function hvPnConLai(s){return num(s.remaining_amount)||num(s.due_amount)}
/* Chọn đợt nào thì ô số tiền tự nhảy theo đợt đó - không bắt người ta tự cộng trừ. */
function hvPnChon(eid){
 var v=fldV("hvpn_dot")||"";
 var a=document.getElementById("hvpn_amt");if(!a)return;
 if(v==="__khac"){a.value="";a.focus();return}
 var s=hvPnDot(eid).filter(function(x){return String(x.installment_no)===String(v)})[0];
 if(s)a.value=String(hvPnConLai(s))}
function hvPaidNotify(eid){
 var e=find("DL06","enrollment_id",eid)||{};
 var ds=hvPnDot(eid), sch=ds[0];
 var h='<div class="dcard"><h4><i class="ti ti-upload"></i>Báo đã chuyển khoản</h4>';
 h+='<div class="notebar" style="margin:0 0 10px"><i class="ti ti-info-circle"></i>Báo ở đây để kế toán đối soát nhanh, bạn không cần gọi điện. Khi đối soát xong, mục Học phí của bạn sẽ tự cập nhật. <b>Trung tâm chỉ ghi tiền vào sổ sau khi đối soát</b> - báo ở đây chưa phải là đã thu.</div>';
 if(ds.length){
  h+='<div class="fld full"><label>Bạn đóng cho đợt nào <i>*</i></label><select id="hvpn_dot" onchange="hvPnChon(\''+esc(eid)+'\')">';
  ds.forEach(function(s,i){
   var qh=pvnd(s.due_date), tre=(qh&&qh.getTime()<Date.now());
   h+='<option value="'+esc(s.installment_no)+'"'+(i===0?" selected":"")+'>Đợt '+esc(s.installment_no)+
    ' · hạn '+esc(s.due_date||"chưa hẹn")+' · '+vnd(hvPnConLai(s))+(tre?" · ĐANG QUÁ HẠN":"")+'</option>'});
  h+='<option value="__khac">Đóng trước cho nhiều đợt / số khác</option></select></div>';
 }else{
  h+='<div class="fhint" style="margin:0 0 10px">Đăng ký này chưa có bảng đợt đóng - bạn cứ nhập số tiền đã chuyển, kế toán sẽ ghi đúng chỗ.</div>';
 }
 h+='<div class="fld"><label>Số tiền đã chuyển <i>*</i></label><input id="hvpn_amt" inputmode="numeric" value="'+esc(sch?String(hvPnConLai(sch)):"")+'"></div>';
 h+='<div class="fld"><label>Ngày chuyển</label><input id="hvpn_date" type="date" max="'+isoDay(0)+'" value="'+isoDay(0)+'"><div class="fhint">Mặc định là hôm nay - lùi lại nếu bạn chuyển từ hôm trước.</div></div>';
 h+='<div class="fld full"><label>Nội dung chuyển khoản / mã giao dịch</label><input id="hvpn_ref" placeholder="vd: HV030 dong hoc phi dot 2"></div>';
 h+=attachBox("hvpn","Ảnh biên lai / màn hình chuyển khoản");
 h+='<div class="dact"><button class="btn primary" onclick="hvPaidNotifySave(\''+esc(eid)+'\')"><i class="ti ti-send"></i>Gửi cho kế toán</button>'+
  '<button class="btn" onclick="closeModal()">Hủy</button></div></div>';
 openDrawer("Tôi đã chuyển khoản",h)}
function hvPaidNotifySave(eid){
 if(!actGuard("hvPaidNotify:"+eid))return;
 var amt=num(fldV("hvpn_amt"));if(amt<=0){toast("Nhập số tiền bạn đã chuyển.");return}
 var e=find("DL06","enrollment_id",eid)||{};
 var rem=num(e.remaining_amount);
 if(rem>0&&amt>rem+1){toast("Số tiền lớn hơn phần còn phải đóng ("+vnd(rem)+") - kiểm lại giúp bạn nhé.",4600);return}
 var dot=(fldV("hvpn_dot")||"").trim();
 var sDot=(dot&&dot!=="__khac")?hvPnDot(eid).filter(function(x){return String(x.installment_no)===dot})[0]:null;
 var moTaDot=sDot?("đợt "+sDot.installment_no+" (hạn "+(sDot.due_date||"chưa hẹn")+", cần "+vnd(hvPnConLai(sDot))+")")
   :(dot==="__khac"?"đóng trước cho nhiều đợt / số khác":"");
 /* KHÔNG tự ghi phiếu thu: tiền chỉ vào sổ khi kế toán đối soát. Đây là BÁO, không phải THU. */
 hvReq("Học viên báo đã chuyển khoản "+vnd(amt)+(sDot?(" - đợt "+sDot.installment_no):""),
  "Đăng ký: "+eid+"\nSố tiền báo: "+vnd(amt)+
  (moTaDot?"\nBáo cho: "+moTaDot:"")+
  ((fldV("hvpn_date")||"").trim()?"\nNgày chuyển: "+fromISOdt(fldV("hvpn_date")).split(" ")[0]:"")+
  ((fldV("hvpn_ref")||"").trim()?"\nNội dung/mã GD: "+(fldV("hvpn_ref")||"").trim():"")+
  attachLine("hvpn").replace(" | ","\n")+
  "\nKế toán đối soát rồi ghi phiếu thu - cổng KHÔNG tự ghi tiền vào sổ.",
  "tien",["enrollment",eid,"Đăng ký "+eid]);
 closeModal();
 toast("Đã báo kế toán"+(sDot?(" cho đợt "+sDot.installment_no):"")+". Sau khi đối soát, mục Học phí của bạn sẽ tự cập nhật.",4600);hvReRender()}

